steps.command:
sudo tee /etc/nginx/conf.d/app-tls.conf > /dev/null <<'EOF'
server {
    listen 443 ssl;
    server_name app.example.mil;
    ssl_protocols TLSv1.2 TLSv1.3;
    ssl_certificate /etc/pki/tls/certs/app-v1-fullchain.pem;
    ssl_certificate_key /etc/pki/tls/private/app-v1.key;
    root /usr/share/nginx/html/tls-lab;
    index index.html;
    location / {
        try_files $uri $uri/ =404;
    }
}
EOF
sudo restorecon -v /etc/nginx/conf.d/app-tls.conf
sudo sed -n '1,30p' /etc/nginx/conf.d/app-tls.conf

$HostsFile = "$env:SystemRoot\System32\drivers\etc\hosts"
if (!(Test-Path "$HostsFile.sonic-tls-backup")) { Copy-Item $HostsFile "$HostsFile.sonic-tls-backup" }
if (!(Select-String -Path $HostsFile -Pattern '\bapp\.example\.mil\b' -Quiet)) { Add-Content -Path $HostsFile -Value "`r`n10.90.0.10 app.example.mil" }
Select-String -Path $HostsFile -Pattern 'app\.example\.mil'
